// 结构树工具模块：总结构树（设备+管路合并）+ 设备结构树 + 管路结构树（基于真实电厂KKS编码数据）
import equipmentRawNodes from './equipmentStructureTree.json';
import pipelineRawNodes from './pipelineStructureTree.json';

// ===== 类型定义 =====
export type TreeType = 'total' | 'equipment' | 'pipeline';

export interface RawNode {
  id: number;
  parentId: number;
  level: string;        // 一级/二级/三级/四级
  category: string;     // 设备/管路/系统目录
  name: string;
  typeCode: string;
  kks: string;
  sort: number;
}

export type NodeLevel = 'L1' | 'L2' | 'L3' | 'L4';

export interface TreeNode {
  id: number;
  parentId: number;
  level: NodeLevel;
  category: 'equipment' | 'pipeline' | 'system';  // 设备/管路/系统目录
  name: string;
  kks: string;
  sort: number;
  matchType?: string;   // 对象类型（设备类型/管路用途），在结构树管理中维护，用于属性模板自动匹配
  childCount: number;     // 直接子节点数
  descendantCount: number; // 所有后代数
  equipmentCount: number;  // 末级设备/管路数
  children?: TreeNode[];
}

// ===== 层级映射 =====
const levelMap: Record<string, NodeLevel> = {
  '一级': 'L1',
  '二级': 'L2',
  '三级': 'L3',
  '四级': 'L4',
};

// ===== 数据源 =====
// 归一化 parentId：部分原始数据把父节点对象整体嵌入 parentId 字段，统一取其 id
const normalizeRaw = (raw: RawNode[]): RawNode[] =>
  raw.map((n) => ({
    ...n,
    parentId: typeof n.parentId === 'number' ? n.parentId : (n.parentId as any)?.id ?? n.parentId,
  }));

const equipmentNodes = normalizeRaw(equipmentRawNodes as RawNode[]);
const pipelineNodes = normalizeRaw(pipelineRawNodes as RawNode[]);

// 管路数据 id 整体偏移，避免与设备数据 id 冲突（设备数据最大 id 远小于 10000）
const PIPELINE_ID_OFFSET = 10000;
const totalRawNodes: RawNode[] = [
  ...equipmentNodes,
  ...pipelineNodes.map((n) => ({
    ...n,
    id: n.id + PIPELINE_ID_OFFSET,
    parentId: n.parentId === 0 ? 0 : n.parentId + PIPELINE_ID_OFFSET,
  })),
];

const dataSources: Record<TreeType, RawNode[]> = {
  total: totalRawNodes,
  equipment: equipmentNodes,
  pipeline: pipelineNodes,
};

// 叶子节点类别（用于统计末级数量）
const leafCategories: Record<TreeType, string[]> = {
  total: ['设备', '管路'],
  equipment: ['设备'],
  pipeline: ['管路'],
};

// 原始分类 → 节点分类（总结构树同时包含设备与管路末级节点）
const rawCategoryToType = (rawCategory: string): TreeNode['category'] => {
  if (rawCategory === '设备') return 'equipment';
  if (rawCategory === '管路') return 'pipeline';
  return 'system';
};

// ===== 统计每个节点的后代数和设备/管路数 =====
function computeCounts(raw: RawNode[], leafCats: string[]): Map<number, { descendant: number; equipment: number }> {
  const counts = new Map<number, { descendant: number; equipment: number }>();
  raw.forEach((n) => counts.set(n.id, { descendant: 0, equipment: 0 }));
  const childMap = new Map<number, number[]>();
  raw.forEach((n) => {
    if (n.parentId >= 0) {
      if (!childMap.has(n.parentId)) childMap.set(n.parentId, []);
      childMap.get(n.parentId)!.push(n.id);
    }
  });
  raw.forEach((n) => {
    const hasChild = childMap.has(n.id) && childMap.get(n.id)!.length > 0;
    if (!hasChild && leafCats.includes(n.category)) {
      counts.set(n.id, { descendant: 0, equipment: 1 });
    }
  });
  const sorted = [...raw].sort((a, b) => b.id - a.id);
  sorted.forEach((n) => {
    if (n.parentId > 0) {
      const parent = counts.get(n.parentId);
      const self = counts.get(n.id);
      if (parent && self) {
        parent.descendant += 1 + self.descendant;
        parent.equipment += self.equipment;
      }
    }
  });
  return counts;
}

const countsCache: Record<TreeType, Map<number, { descendant: number; equipment: number }>> = {
  total: computeCounts(dataSources.total, leafCategories.total),
  equipment: computeCounts(dataSources.equipment, leafCategories.equipment),
  pipeline: computeCounts(dataSources.pipeline, leafCategories.pipeline),
};

// ===== 构建树 =====
export function buildStructureTree(treeType: TreeType = 'equipment'): TreeNode[] {
  const raw = dataSources[treeType];
  const counts = countsCache[treeType];
  const leafCats = leafCategories[treeType];

  const childMap = new Map<number, RawNode[]>();
  raw.forEach((n) => {
    if (n.parentId >= 0) {
      if (!childMap.has(n.parentId)) childMap.set(n.parentId, []);
      childMap.get(n.parentId)!.push(n);
    }
  });

  const build = (parentId: number): TreeNode[] => {
    const children = childMap.get(parentId) || [];
    return children
      .sort((a, b) => a.sort - b.sort)
      .map((n) => {
        const c = counts.get(n.id) || { descendant: 0, equipment: 0 };
        const nodeChildren = build(n.id);
        const category: TreeNode['category'] = treeType === 'total'
          ? rawCategoryToType(n.category)
          : leafCats.includes(n.category)
            ? (treeType === 'equipment' ? 'equipment' : 'pipeline')
            : 'system';
        return {
          id: n.id,
          parentId: n.parentId,
          level: levelMap[n.level] || 'L1',
          category,
          name: n.name,
          kks: n.kks,
          sort: n.sort,
          childCount: nodeChildren.length,
          descendantCount: c.descendant,
          equipmentCount: c.equipment,
          children: nodeChildren.length > 0 ? nodeChildren : undefined,
        };
      });
  };

  return build(0);
}

// ===== 查询函数（纯函数，适用于任意TreeNode[]） =====
export function findNode(nodes: TreeNode[], id: number): TreeNode | null {
  for (const n of nodes) {
    if (n.id === id) return n;
    if (n.children) {
      const found = findNode(n.children, id);
      if (found) return found;
    }
  }
  return null;
}

// 获取所有后代ID
export function getDescendantIds(nodes: TreeNode[], id: number): number[] {
  const node = findNode(nodes, id);
  if (!node || !node.children) return [];
  const ids: number[] = [];
  const walk = (n: TreeNode) => {
    n.children?.forEach((c) => {
      ids.push(c.id);
      walk(c);
    });
  };
  walk(node);
  return ids;
}

// 获取节点路径（从根到该节点）
export function getNodePath(nodes: TreeNode[], id: number): TreeNode[] {
  const path: TreeNode[] = [];
  const find = (arr: TreeNode[], targetId: number): boolean => {
    for (const n of arr) {
      if (n.id === targetId) {
        path.push(n);
        return true;
      }
      if (n.children && find(n.children, targetId)) {
        path.unshift(n);
        return true;
      }
    }
    return false;
  };
  find(nodes, id);
  return path;
}

// 搜索匹配的节点key集合（含祖先）
export function collectMatchKeys(nodes: TreeNode[], keyword: string): Set<number> {
  const result = new Set<number>();
  const kw = keyword.trim().toLowerCase();
  if (!kw) return result;
  const walk = (n: TreeNode): boolean => {
    let childMatch = false;
    n.children?.forEach((c) => { if (walk(c)) childMatch = true; });
    const selfMatch = n.name.toLowerCase().includes(kw) || n.kks.toLowerCase().includes(kw);
    if (selfMatch || childMatch) {
      result.add(n.id);
      return true;
    }
    return false;
  };
  nodes.forEach((n) => walk(n));
  return result;
}

// ===== 统计信息 =====
export function getTreeStats(treeType: TreeType = 'equipment') {
  const raw = dataSources[treeType];
  const leafCats = leafCategories[treeType];
  const l1 = raw.filter((n) => n.level === '一级').length;
  const l2 = raw.filter((n) => n.level === '二级').length;
  const l3 = raw.filter((n) => n.level === '三级').length;
  const l4 = raw.filter((n) => n.level === '四级').length;
  const leaf = raw.filter((n) => leafCats.includes(n.category)).length;
  const system = raw.filter((n) => n.category === '系统目录').length;
  return { total: raw.length, l1, l2, l3, l4, equipment: leaf, system };
}

// 获取一级分类列表
export function getRootCategories(treeType: TreeType = 'equipment'): RawNode[] {
  return dataSources[treeType]
    .filter((n) => n.level === '一级')
    .sort((a, b) => a.sort - b.sort);
}

// 根据KKS前缀查找节点
export function findByKksPrefix(nodes: TreeNode[], prefix: string): TreeNode | null {
  const kw = prefix.trim().toUpperCase();
  if (!kw) return null;
  const find = (arr: TreeNode[]): TreeNode | null => {
    for (const n of arr) {
      if (n.kks.toUpperCase() === kw) return n;
      if (n.children) {
        const found = find(n.children);
        if (found) return found;
      }
    }
    return null;
  };
  return find(nodes);
}

// 获取原始数据（供管理页面使用）
export function getRawNodes(treeType: TreeType = 'equipment'): RawNode[] {
  return dataSources[treeType];
}

// ===== 勾选派生相关（设备/管路结构树由总结构树勾选生成） =====

// 统计节点总数
export function countNodes(nodes: TreeNode[]): number {
  let count = 0;
  const walk = (arr: TreeNode[]) => {
    arr.forEach((n) => {
      count += 1;
      if (n.children) walk(n.children);
    });
  };
  walk(nodes);
  return count;
}

// 收集某节点子树内全部节点ID（含自身）
export function collectSubtreeIds(nodes: TreeNode[], id: number): number[] {
  const node = findNode(nodes, id);
  if (!node) return [];
  const ids: number[] = [];
  const walk = (n: TreeNode) => {
    ids.push(n.id);
    n.children?.forEach(walk);
  };
  walk(node);
  return ids;
}

// 根据已勾选的节点集合，从总结构树中提取子树（保留祖先链并重算计数）
export function buildSubTreeFromNodes(nodes: TreeNode[], selectedNodeIds: Set<number>): TreeNode[] {
  // 节点是否保留：自身被勾选，或存在被勾选的后代
  const keep = (n: TreeNode): boolean => {
    if (selectedNodeIds.has(n.id)) return true;
    if (n.children) return n.children.some(keep);
    return false;
  };
  const build = (arr: TreeNode[]): TreeNode[] => {
    const out: TreeNode[] = [];
    arr.forEach((n) => {
      if (!keep(n)) return;
      const children = n.children ? build(n.children) : [];
      const descendantCount = children.reduce((sum, c) => sum + 1 + c.descendantCount, 0);
      const equipmentCount = children.reduce((sum, c) => sum + c.equipmentCount, 0) + (children.length === 0 ? 1 : 0);
      out.push({
        ...n,
        childCount: children.length,
        descendantCount,
        equipmentCount,
        children: children.length > 0 ? children : undefined,
      });
    });
    return out;
  };
  return build(nodes);
}

// 按 KKS 编码在树中查找节点
export function findNodeByKks(nodes: TreeNode[], kks: string): TreeNode | null {
  for (const n of nodes) {
    if (n.kks && n.kks === kks) return n;
    if (n.children) {
      const found = findNodeByKks(n.children, kks);
      if (found) return found;
    }
  }
  return null;
}

// 获取总结构树：优先读取结构树管理页面持久化的数据（含对象类型维护），无则按初始数据构建
export function getTotalTreeCached(): TreeNode[] {
  try {
    const saved = localStorage.getItem("structureTree.total");
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) return parsed as TreeNode[];
    }
  } catch { /* 忽略异常 */ }
  return buildStructureTree("total");
}
